-- Версия 0.50.0: большое обновление оформления (заменяет промежуточные записи 0.39–0.49).
-- Формат пунктов: kind = new | fixed | improved, min_rank: 1 все, 2 админы по предметам и выше, 3 админы, 4 главный админ.
select public.add_site_release(
  '0.50.0',
  'Большое обновление: новый вид сайта',
  jsonb_build_array(
    jsonb_build_object('kind', 'new',      'min_rank', 1, 'text', 'Тёмная тема: кнопка с луной в шапке (на телефоне — меню «Ещё») переключает оформление; по умолчанию остаётся светлая'),
    jsonb_build_object('kind', 'new',      'min_rank', 1, 'text', 'На большом экране слева появилось меню с разделами по группам, его можно свернуть до значков'),
    jsonb_build_object('kind', 'improved', 'min_rank', 1, 'text', 'Рабочая область стала шире: фильтры и состав билета закреплены сбоку, архив показывает наборы в несколько колонок'),
    jsonb_build_object('kind', 'improved', 'min_rank', 1, 'text', 'Перед удалением и другими важными действиями открывается понятное окно с объяснением, что произойдёт, и подписанными кнопками'),
    jsonb_build_object('kind', 'improved', 'min_rank', 1, 'text', 'Кнопки, поля и подписи стали крупнее и единообразнее, по ним легче попасть пальцем на телефоне'),
    jsonb_build_object('kind', 'improved', 'min_rank', 1, 'text', 'Пока данные загружаются, показываются серые заготовки карточек, а пустые разделы подсказывают, что делать дальше'),
    jsonb_build_object('kind', 'new',      'min_rank', 1, 'text', 'Рядом со сложными словами появились значки «?» с короткими пояснениями; термины «набор», «партия» и «билет» теперь везде значат одно и то же'),
    jsonb_build_object('kind', 'improved', 'min_rank', 1, 'text', 'Значки-кнопки (удалить, править, закрыть, копировать) подписаны и понятны программам для слепых'),
    jsonb_build_object('kind', 'fixed',    'min_rank', 1, 'text', 'Исправлено: на телефоне страницы «Пользователи», «Статистика» и «Корзина» уезжали вбок'),
    jsonb_build_object('kind', 'new',      'min_rank', 2, 'text', 'В форме вопроса справа показывается предпросмотр, а список «Готовность вопроса» подсказывает, что ещё нужно заполнить'),
    jsonb_build_object('kind', 'fixed',    'min_rank', 2, 'text', 'Кнопка удаления картинки в форме вопроса и корзины в «Предметах и темах» теперь видны и на телефоне, а не только при наведении мыши'),
    jsonb_build_object('kind', 'improved', 'min_rank', 2, 'text', 'При импорте вопросов предварительный просмотр открывается справа от настроек'),
    jsonb_build_object('kind', 'improved', 'min_rank', 3, 'text', 'Раздел «Пользователи» перестроен: список людей слева, форма нового аккаунта и журнал действий справа; у статистики появился заголовок')
  ),
  '2026-11-11 12:00:00+05'
);
